INSERT INTO word_glossary (word, vn, pos, ipa, source, audio_src) VALUES
  ('the', 'cái, con, người...; ấy, này (người, cái, con...); duy nhất (người, vật...)', 'mạo từ', '/ðə/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/the__/the__us_1_rr.mp3'),
  ('be', 'thì, là; có, tồn tại, ở, sống; trở nên, trở thành', '(bất qui tắc) nội động từ & trợ động từ (số ít was,  số nhiều were,  been)', '/bi/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/be_/be__u/be__us_1.mp3'),
  ('and', 'và, cùng, với; nếu dường như, tuồng như là; còn', 'liên từ', '/ənd/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/and/and__/and__us_1.mp3'),
  ('of', 'của; xpia; thuộc, của, ở', 'giới từ', '/əv/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/of_/of__u/of__us_1_rr.mp3'),
  ('to', 'đến, tới, về; cho đến; cho, với', 'giới từ,  (từ cổ,nghĩa cổ),  (thơ ca) unto', '/tə/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/to_/to__u/to__us_1_rr.mp3'),
  ('a', NULL, NULL, '/ə/', 'oxford', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/a__/a__us/a__us_2_rr.mp3'),
  ('in', 'ở, tại, trong (nơi chốn, không gian...); xpia; về, vào, vào lúc, trong, trong lúc (thời gian)', 'giới từ', '/ɪn/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/in_/in__u/in__us_1.mp3'),
  ('have', 'có; (+ from) nhận được, biết được; ăn; uống; hút', 'động từ had', '/həv/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hav/have_/have__us_1_rr.mp3'),
  ('it', 'cái đó, điều đó, con vật đó; trời, thời tiết; ngày; đường...; em bé', 'đại từ', '/ɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/it_/it__u/it__us_2.mp3'),
  ('you', 'anh, chị, ông, bà, ngài, ngươi, mày; các anh, các chị, các ông, các bà, các ngài, các người, chúng mày; ai', 'đại từ', '/jə/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/you/you__/you__us_1_rr.mp3'),
  ('he', 'nó, anh ấy, ông ấy... (chỉ người và động vật giống đực)* danh từ; đàn ông; con đực', 'đại từ', '/hi/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/he_/he__u/he__us_1.mp3'),
  ('for', 'thay cho, thế cho, đại diện cho; ủng hộ, về phe, về phía; để, với mục đích là', 'giới từ', '/fər/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/for__/for__us_1_rr.mp3'),
  ('they', 'chúng nó, chúng, họ; người ta', 'danh từ', '/ðeɪ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/they_/they__us_1.mp3'),
  ('not', 'không; hẳn là, chắc là; (xem) but', 'phó từ', '/nɑːt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/not__/not__us_1.mp3'),
