  ('on', 'trên, ở trên; dựa trên, dựa vào; vào, lúc khi', 'danh từ', '/ɑːn/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/on_/on__u/on__us_1_rr.mp3'),
  ('with', 'với, cùng, cùng với; có; ở, ở ni', 'giới từ', '/wɪð/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/with_/with__us_1_rr.mp3'),
  ('this', 'này; cái này, điều này, việc này; thế này', 'tính từ chỉ định,  số nhiều these', '/ðɪs/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/this_/this__us_1.mp3'),
  ('as', 'như; là, với tư cách là; cũng, bằng', 'phó từ', '/əz/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/as_/as__u/as__us_1_rr.mp3'),
