  ('from', 'từ; nội; dựa vào, theo, do từ, xuất phát từ', 'giới từ', '/frəm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fro/from_/from__us_1_rr.mp3'),
  ('by', 'gần, cạnh, kế, bên; về phía; qua, ngang qua, xuyên qua, dọc theo (chỉ hướng và chuyển động)', 'danh từ', '/baɪ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/by_/by__u/by__us_1.mp3'),
  ('will', 'ý chí, chí, ý định, lòng; sự hăng say; sự quyết chí, sự quyết tâm; nguyện vọng, ý muốn; ý thích', 'danh từ', '/wɪl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wil/will_/will__us_1.mp3'),
  ('or', 'vàng (ở huy hiệu)* giới từ & liên từ; (từ cổ,nghĩa cổ) trước, trước khi* liên từ; hoặc, hay là', 'danh từ', '/ɔːr/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/or_/or__u/or__us_2_rr.mp3'),
