  ('which', 'nào (ngụ ý chọn lựa); bất cứ... nào; ấy, đó', 'tính từ', '/wɪtʃ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/which/which__us_1.mp3'),
  ('there', 'ở đó, tại đó, chỗ đó, chỗ ấy, đấy; đó, đấy; chỗ đó, nơi đó, chỗ đấy', 'phó từ', '/ðer/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/there__us_1.mp3'),
  ('know', 'biết; hiểu biết; biết, nhận biết; phân biệt được; biết, quen biết', 'động từ knew; known', '/nəʊ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/know_/know__us_1.mp3'),
  ('more', 'nhiều hơn, lớn hơn, đông hơn; hơn nữa, thêm nữa, thêm nữa; hơn, nhiều hơn', 'tính từ (cấp so sánh của many & much)', '/mɔːr/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/more_/more__us_1.mp3'),
  ('get', 'được, có được, kiếm được, lấy được; nhận được, xin được, hỏi được; tìm ra, tính ra', 'ngoại động từ got,  got,  gotten', '/ɡet/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/get/get__/get__us_1.mp3'),
