  ('time', 'thời gian, thì giờ; thời, thời buổi, mùa; dịp, cơ hội, thời cơ', 'danh từ', '/taɪm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tim/time_/time__us_1.mp3'),
  ('see', 'thấy, trông thấy, nhìn thấy; xem, quan sát, xem xét; xem, đọc (trang báo chí)', 'động từ saw/saw/,  seen/seen/', '/siː/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/see__/see__us_1.mp3'),
