  ('some', 'nào đó; một ít, một vài, dăm ba; khá nhiều, đáng kể', 'tính từ', '/sʌm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/some_/some__us_1_rr.mp3')
