  ('percentage', 'tỷ lệ phần trăm; tỷ lệ; phần', 'danh từ', '/pərˈsentɪdʒ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/percentage__us_2.mp3'),
  ('peace', 'hoà bình, thái bình, sự hoà thuận; ((thường) Peace) hoà ước; sự yên ổn, sự trật tự an ninh', 'danh từ', '/piːs/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pea/peace/peace__us_1.mp3'),
