  ('reform', 'sự cải cách, sự cải lương, sự cải thiện, sự cải tạo, sự cải tổ; sự sửa đổi; cải cách, cải lương, cải thiện', 'danh từ', '/rɪˈfɔːrm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refor/reform__us_1.mp3'),
