INSERT INTO word_glossary (word, vn, pos, ipa, source, audio_src) VALUES
  ('implicate', 'ẩn ý, điều ngụ ý; điều ngụ ý* ngoại động từ; lôi kéo vào, làm vướng vào, làm liên can vào, làm dính líu vào', 'danh từ', '/ˈɪmplɪkeɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implicate__us_1.mp3'),
