  ('label', 'nhãn, nhãn hiệu; danh hiệu; chiêu bài; (kiến trúc) mái hắt* ngoại động từ', 'danh từ', '/ˈleɪbl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/label/label__us_4.mp3'),
  ('mechanism', 'máy móc, cơ cấu, cơ chế ((nghĩa đen) & (nghĩa bóng)); kỹ thuật, kỹ xảo; (triết học) thuyết cơ giới', 'danh từ', '/ˈmekənɪzəm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mec/mecha/mechanism__us_1.mp3'),
