  ('simulate', 'giả vờ, giả cách; đóng vai; đội lốt; bắt chước; dựa theo', 'ngoại động từ', '/ˈsɪmjuleɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simul/simulate__us_1.mp3'),
  ('sole', '(động vật học) cá bơn; bàn chân; đế giày', 'danh từ', '/səʊl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/sole_/sole__us_1.mp3'),
  ('somewhat', 'hơi, gọi là, một chút', 'phó từ', '/ˈsʌmwʌt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhat__us_1.mp3'),
  ('submit', 'to submit oneself to... chịu phục tùng...; đệ trình, đưa ra ý kiến là; chịu, cam chịu, quy phục', 'ngoại động từ', '/səbˈmɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/submi/submit__us_1.mp3')
INSERT INTO word_glossary (word, vn, pos, ipa, source, audio_src) VALUES
