  ('thesis', 'luận văn, luận án; luận điểm, luận đề, thuyết; chính đề', 'danh từ,  số nhiều theses', '/ˈθiːsɪs/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/thesi/thesis__us_1.mp3'),
  ('transmit', 'chuyển giao, truyền', 'ngoại động từ', '/trænzˈmɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transmit__us_2_rr.mp3'),
  ('ultimate', 'cuối cùng, sau cùng, chót; cơ bản, chủ yếu; (từ Mỹ,nghĩa Mỹ) lớn nhất, tối đa* danh từ', 'tính từ', '/ˈʌltɪmət/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ult/ultim/ultimate__us_1.mp3'),
  ('unique', 'chỉ có một, duy nhất, đơn nhất, vô song; (thông tục) kỳ cục, lạ đời, dị thường; vật duy nhất', 'tính từ', '/juˈniːk/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/uniqu/unique__us_1.mp3'),
