  ('ambiguous', 'tối nghĩa; không rõ ràng, mơ hồ; nước đôi, nhập nhằng', 'tính từ', '/æmˈbɪɡjuəs/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amb/ambig/ambiguous__us_1.mp3'),
  ('append', 'treo vào; cột vào, buộc vào, nối vào, chấp vào; gắn vào; viết thêm vào; đóng (dấu), áp (triện...); ký tên', 'ngoại động từ', '/əˈpend/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appen/append__us_1.mp3'),
