  ('conform', '(+ to) làm cho hợp với, làm cho phù hợp với, làm cho thích hợp với; to conform oneself to thích nghi với', 'ngoại động từ', '/kənˈfɔːrm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconform__us_1.mp3'),
  ('contemporary', 'đương thời; cùng thời; cùng tuổi (người); xuất bản cùng thời (báo chí); hiện đại (lịch sử)* danh từ', 'tính từ', '/kənˈtempəreri/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontemporary__us_1.mp3'),
  ('contradict', 'mâu thuẫn với, trái với; cãi lại, phủ nhận', 'ngoại động từ', '/ˌkɑːntrəˈdɪkt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontradict__us_1.mp3'),
  ('crucial', 'quyết định; cốt yếu, chủ yếu; (y học) hình chữ thập', 'tính từ', '/ˈkruːʃl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cru/cruci/crucial__us_1.mp3'),
