  ('intense', 'mạnh, có cường độ lớn; mãnh liệt, dữ dội; nồng nhiệt, sôi nổi (tình cảm, hành động...)', 'tính từ', '/ɪnˈtens/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intense__us_3.mp3'),
  ('manipulate', 'vận dụng bằng tay, thao tác; lôi kéo, vận động (bằng mánh khoé)', 'ngoại động từ', '/məˈnɪpjuleɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manip/manipulate__us_1.mp3'),
  ('offset', 'chồi cây, mầm cây; núi ngang, hoành sơn; sự đền bù, sự bù đắp', 'danh từ', '/ˈɔːfset/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offse/offset__us_1_rr.mp3'),
  ('paragraph', 'đoạn văn; dấu mở đầu một đoạn văn; dấu xuống dòng; mẫu tin (trên báo, thường không có đề)* ngoại động từ', 'danh từ', '/ˈpærəɡræf/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parag/paragraph__us_1.mp3'),
  ('practitioner', 'thầy thuốc đang hành nghề; luật sư đang hành nghề; (xem) general', 'danh từ', '/prækˈtɪʃənər/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practitioner__us_1.mp3'),
  ('predominant', 'chiếm ưu thế, trội hơn hẳn', 'tính từ', '/prɪˈdɑːmɪnənt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predo/predominant__us_1.mp3'),
  ('prospect', 'cảnh, toàn cảnh, viễn cảnh; viễn tượng; hy vọng ở tương lai, triển vọng tương lai, tiền đồ', 'danh từ', '/ˈprɑːspekt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prosp/prospect__us_1.mp3'),
  ('radical', 'gốc, căn bản; (chính trị) cấp tiến; đảng Cấp tiến', 'tính từ', '/ˈrædɪkl/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radic/radical__us_1.mp3'),
  ('random', 'at random càn, bậy bạ; ẩu, bừa bâi; to speak at random nói bậy bạ; to shoot at random bắn càn', 'danh từ', '/ˈrændəm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rando/random__us_1.mp3'),
  ('reinforce', 'tăng cường, củng cố; tăng viện; tăng thêm sức mạnh; cái làm cho vững chắc thêm; đại củng cố', 'ngoại động từ', '/ˌriːɪnˈfɔːrs/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rei/reinf/reinforce__us_1.mp3')
INSERT INTO word_glossary (word, vn, pos, ipa, source, audio_src) VALUES
  ('restore', 'hoàn lại, trả lại; sửa chữa lại, phục hồi lại, xây dựng lại như cũ (toà nhà, bức tranh...); phục (chức)', 'ngoại động từ', '/rɪˈstɔːr/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resto/restore__us_1.mp3'),
  ('revise', 'đọc lại, xem lại, duyệt lại, xét lại; sửa (bản in thử); sửa đổi (đạo luật...)', 'ngoại động từ', '/rɪˈvaɪz/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revis/revise__us_3.mp3'),
