  ('terminate', 'vạch giới hạn, định giới hạn; làm xong, kết thúc, hoàn thành, chấm dứt; xong, kết thúc, chấm dứt, kết cục', 'ngoại động từ', '/ˈtɜːrmɪneɪt/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/termi/terminate__us_1.mp3'),
  ('theme', 'đề tài, chủ đề; (ngôn ngữ nhà trường) luận văn, bài luận; (ngôn ngữ học) chủ tố', 'danh từ', '/θiːm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theme/theme__us_1.mp3'),
  ('thereby', 'bằng cách ấy, theo cách ấy, do đó; có dính dáng tới cái đó, có liên quan tới cái đó', 'phó từ', '/ˌðerˈbaɪ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/thereby__us_1_rr.mp3'),
  ('uniform', 'đồng dạng, cùng một kiểu, giống nhau; không thay đổi, không biến hoá, đều; đồng phục', 'tính từ', '/ˈjuːnɪfɔːrm/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unifo/uniform__us_1.mp3'),
